window.TRILHA_GOLD_BANKS=window.TRILHA_GOLD_BANKS||{};window.TRILHA_GOLD_BANKS["v5-sm-A2"]={"id":"sm-A2","title":"Síndromes hipertensivas gestacionais | 30 questões clínicas autorais","group":"P2 • Saúde da Mulher II","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","version":"5.1.0","questions":[{"id":"ouro-rigor5-sm-A2-01","topicId":"sm-A2","stem":"Gestante primigesta de 24 semanas apresenta PA de 146/94 mmHg e 148/92 mmHg em medidas corretas confirmadas no serviço. Antes da gestação era normotensa; não há proteinúria, sintomas, disfunção orgânica ou alterações fetais. Qual classificação inicial é mais adequada?","options":["Hipertensão arterial crônica, porque qualquer PA elevada na gravidez implica doença preexistente.","Pré-eclâmpsia grave, porque duas medidas acima de 140/90 já demonstram lesão orgânica.","Síndrome HELLP, mesmo com plaquetas e transaminases normais.","Hipertensão gestacional com vigilância de progressão para pré-eclâmpsia.","Elevação fisiológica da pressão na gestação, sem necessidade de vigilância."],"answer":3,"analysis":["INCORRETA. A cronologia após 20 semanas e histórico anterior são essenciais para a classificação.","INCORRETA. Não foram demonstradas manifestações de gravidade ou disfunção sistêmica.","INCORRETA. HELLP depende de achados hematológicos/hepáticos característicos.","CORRETA. Hipertensão nova após 20 semanas sem critérios de pré-eclâmpsia caracteriza hipertensão gestacional, que exige seguimento porque pode progredir.","INCORRETA. PA persistentemente ≥140/90 não é achado fisiológico e demanda acompanhamento."],"explanation":"Hipertensão nova após 20 semanas sem critérios de pré-eclâmpsia caracteriza hipertensão gestacional, que exige seguimento porque pode progredir.","memorizar":"PA NOVA após 20 semanas SEM proteinúria/disfunção: hipertensão gestacional, monitorar evolução.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"hipertensão gestacional","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sm-A2-02","topicId":"sm-A2","stem":"Grávida de 13 semanas, sem registros prévios, procura pré-natal com PA de 152/98 mmHg em avaliações repetidas. Função renal é normal e não há sintomas de alarme. Qual enquadramento temporal é o mais consistente?","options":["Hipertensão gestacional obrigatória, porque toda medida obtida durante a gravidez recebe esse nome.","Hipertensão crônica identificada antes da 20ª semana.","Pré-eclâmpsia precoce confirmada sem outras evidências.","Pressão normal para a gestação porque não há cefaleia.","Eclâmpsia silenciosa, já que PA sistólica acima de 150 define convulsão iminente."],"answer":1,"analysis":["INCORRETA. A definição habitual de hipertensão gestacional exige início após 20 semanas.","CORRETA. Hipertensão antes de 20 semanas sugere doença crônica prévia ou previamente não reconhecida, em vez de hipertensão gestacional típica.","INCORRETA. Pré-eclâmpsia antes de 20 semanas é rara e requer investigação de situações especiais; não é diagnóstico automático.","INCORRETA. A classificação usa valores pressóricos e tempo, não exige sintomas.","INCORRETA. Eclâmpsia envolve convulsões sem explicação melhor; PA isolada não a define."],"explanation":"Hipertensão antes de 20 semanas sugere doença crônica prévia ou previamente não reconhecida, em vez de hipertensão gestacional típica.","memorizar":"ANTES DE 20 SEMANAS: pensar em HIPERTENSÃO CRÔNICA.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"hipertensão crônica antes de 20 semanas","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"},{"id":"ouro-rigor5-sm-A2-03","topicId":"sm-A2","stem":"Gestante de 30 semanas apresenta PA 154/102 mmHg confirmada, plaquetas 82.000/mm³ e transaminases elevadas. A relação proteína/creatinina urinária é inferior ao ponto de corte para proteinúria. Qual conclusão evita subdiagnóstico?","options":["Excluir pré-eclâmpsia porque proteinúria é requisito absolutamente obrigatório.","Reclassificar como hipertensão gestacional benigna pela falta de proteinúria.","Atribuir alterações hematológicas ao hemodilucional normal sem investigação.","Diagnosticar diabetes gestacional como única explicação das plaquetas baixas.","Pré-eclâmpsia com sinal de gravidade mesmo sem proteinúria."],"answer":4,"analysis":["INCORRETA. Critérios atuais contemplam disfunção orgânica materna sem proteinúria.","INCORRETA. Plaquetas baixas e transaminases alteradas são sinais de alerta.","INCORRETA. Plaquetopenia importante com hipertensão exige avaliação urgente.","INCORRETA. Diabetes não explica isoladamente esse padrão de disfunção orgânica aguda.","CORRETA. Trombocitopenia significativa e alteração hepática em hipertensão de início recente satisfazem critérios de dano de órgão alvo, mesmo sem proteinúria."],"explanation":"Trombocitopenia significativa e alteração hepática em hipertensão de início recente satisfazem critérios de dano de órgão alvo, mesmo sem proteinúria.","memorizar":"PRÉ-ECLÂMPSIA não exige proteinúria se há lesão orgânica compatível.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"pré-eclâmpsia sem proteinúria","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-04","topicId":"sm-A2","stem":"Gestante de 27 semanas, PA 149/96 mmHg persistente, faz dosagem de proteína urinária em 24 horas: 520 mg. Hemograma, creatinina e transaminases estão normais e não há sintomas de gravidade. Qual classificação descreve o conjunto?","options":["Pré-eclâmpsia sem sinais de gravidade documentados no momento.","Hipertensão crônica por proteinúria, independentemente do início dos sintomas.","Eclâmpsia, porque proteinúria superior a 300 mg equivale a convulsão.","HELLP, pois proteína urinária de 520 mg comprova hemólise.","Hipertensão gestacional sem pré-eclâmpsia, porque proteinúria tem importância apenas acima de 1 g."],"answer":0,"analysis":["CORRETA. Hipertensão após 20 semanas acompanhada de proteinúria ≥300 mg/24h sustenta pré-eclâmpsia; os dados não demonstram gravidade, embora evolução exija vigilância.","INCORRETA. Proteinúria não determina cronologia de hipertensão.","INCORRETA. Eclâmpsia é definida por crise convulsiva atribuída à condição.","INCORRETA. HELLP requer hemólise, enzimas hepáticas elevadas e plaquetopenia.","INCORRETA. O ponto de corte clássico em coleta de 24h é ≥300 mg."],"explanation":"Hipertensão após 20 semanas acompanhada de proteinúria ≥300 mg/24h sustenta pré-eclâmpsia; os dados não demonstram gravidade, embora evolução exija vigilância.","memorizar":"PROTEINÚRIA ≥300 mg/24h com HAS após 20 semanas sustenta PRÉ-ECLÂMPSIA.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"proteinúria e classificação","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sm-A2-05","topicId":"sm-A2","stem":"Grávida de 32 semanas chega com PA 150/94 mmHg e edema leve. Para avaliação inicial de proteinúria, colhe-se relação proteína/creatinina urinária de 0,42 mg/mg. Qual interpretação é apropriada?","options":["O valor indica ausência de proteinúria porque está abaixo de 1,0.","Esse exame determina, sozinho, HELLP ou eclâmpsia.","Proteinúria significativa pela relação proteína/creatinina de 0,42.","A relação é irrelevante em gestantes; só a presença de edema define pré-eclâmpsia.","O resultado exige aguardar 24 horas sem nenhuma vigilância ou decisão obstétrica."],"answer":2,"analysis":["INCORRETA. O ponto de corte diagnóstico frequentemente adotado é ≥0,3 mg/mg.","INCORRETA. O resultado não avalia hemólise, plaquetas ou convulsões.","CORRETA. A relação proteína/creatinina de amostra isolada pode substituir coleta de 24h para pesquisa de proteinúria de relevância diagnóstica.","INCORRETA. Edema é pouco específico; proteinúria é um dos elementos avaliados.","INCORRETA. A gravidade clínica deve ser investigada prontamente."],"explanation":"A relação proteína/creatinina de amostra isolada pode substituir coleta de 24h para pesquisa de proteinúria de relevância diagnóstica.","memorizar":"PROTEÍNA/CREATININA urinária ≥0,3 é marcador de proteinúria significativa.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"relação proteína-creatinina","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sm-A2-06","topicId":"sm-A2","stem":"Gestante de 33 semanas apresenta PA 168/112 mmHg, confirmada prontamente, cefaleia intensa e pontos brilhantes no campo visual. Ainda se aguarda a proteinúria. Qual prioridade é correta?","options":["Esperar proteinúria de 24 horas para tratar, porque a gravidade pressórica isolada não importa.","Liberar a paciente porque apenas a PA diastólica acima de 120 é preocupante.","Administrar anti-hipertensivo oral contraindicado à gestação como primeira opção universal.","Atribuir fotopsias a mal-estar habitual, sem avaliação neurológica.","Tratar pressão grave sem esperar resultados urinários."],"answer":4,"analysis":["INCORRETA. Pressão grave exige manejo independentemente de proteinúria.","INCORRETA. O limiar de gravidade já foi ultrapassado.","INCORRETA. A escolha deve respeitar medicamentos seguros e protocolos obstétricos.","INCORRETA. Sintomas visuais podem refletir acometimento cerebral.","CORRETA. Pressão sistólica ≥160 ou diastólica ≥110 persistente, sobretudo com sintomas neurológicos, impõe intervenção célere para reduzir risco materno."],"explanation":"Pressão sistólica ≥160 ou diastólica ≥110 persistente, sobretudo com sintomas neurológicos, impõe intervenção célere para reduzir risco materno.","memorizar":"PA ≥160 sistólica OU ≥110 diastólica PERSISTENTE: agir rapidamente.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"PA grave persistente","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-07","topicId":"sm-A2","stem":"Grávida de 31 semanas com hipertensão de início recente apresenta redução de diurese e creatinina sérica que subiu de 0,6 para 1,4 mg/dL, sem doença renal prévia documentada. Qual manifestação de gravidade está mais diretamente indicada?","options":["Disfunção renal como sinal de gravidade da pré-eclâmpsia.","Variação fisiológica típica da gravidez, pois creatinina costuma aumentar expressivamente.","Diagnóstico isolado de síndrome nefrótica sem avaliar a hipertensão.","Desidratação leve certamente benigna sem necessidade de reavaliação.","Confirmação de síndrome HELLP apenas pelo aumento de creatinina."],"answer":0,"analysis":["CORRETA. Elevação importante da creatinina em gestante hipertensa sinaliza disfunção renal e altera gravidade e conduta.","INCORRETA. Na gestação a creatinina habitual tende a ser menor, e 1,4 mg/dL é preocupante.","INCORRETA. A avaliação deve integrar alterações pressóricas e de órgão alvo.","INCORRETA. Oligúria e aumento de creatinina exigem investigação urgente.","INCORRETA. HELLP é definida por hemólise, enzimas hepáticas e plaquetas."],"explanation":"Elevação importante da creatinina em gestante hipertensa sinaliza disfunção renal e altera gravidade e conduta.","memorizar":"CREATININA ELEVADA/EM ASCENSÃO + HAS gestacional: avaliar GRAVIDADE RENAL.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"oligúria e creatinina","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-08","topicId":"sm-A2","stem":"Gestante de 34 semanas chega com dor epigástrica, náuseas, plaquetas 64.000/mm³, AST 180 U/L, LDH elevado e esquizócitos. A PA é 146/92 mmHg. Qual mecanismo e síndrome mais explicam os achados?","options":["Colestase gestacional simples, pois plaquetas baixas e hemólise são critérios usuais dessa condição.","Gastroenterite viral isolada, porque dor abdominal explica as alterações hematológicas.","Diabetes gestacional descompensado, definido por LDH elevado.","HELLP por hemólise microangiopática, lesão hepática e plaquetopenia.","Síndrome antifosfolípide definida apenas por transaminases elevadas."],"answer":3,"analysis":["INCORRETA. Prurido e ácidos biliares caracterizam colestase, não tríade microangiopática.","INCORRETA. A hemólise e plaquetopenia importantes exigem outra explicação.","INCORRETA. LDH e esfregaço não classificam diabetes.","CORRETA. A tríade hemólise, enzimas hepáticas elevadas e plaquetas baixas caracteriza HELLP, que pode surgir mesmo com hipertensão não tão intensa.","INCORRETA. A tríade aponta HELLP e antifosfolípide requer outros critérios."],"explanation":"A tríade hemólise, enzimas hepáticas elevadas e plaquetas baixas caracteriza HELLP, que pode surgir mesmo com hipertensão não tão intensa.","memorizar":"HELLP = HEMÓLISE + ENZIMAS HEPÁTICAS ↑ + PLAQUETAS ↓.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"HELLP e hemólise","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-09","topicId":"sm-A2","stem":"Grávida de 35 semanas com hipertensão e plaquetopenia refere dor súbita intensa em hipocôndrio direito, irradiação escapular e queda de hemoglobina, sem sangramento genital. Qual complicação grave precisa ser lembrada?","options":["Refluxo gastroesofágico simples como causa suficiente da queda de hemoglobina.","Suspeitar de hematoma subcapsular ou ruptura hepática.","Colelitíase não complicada como diagnóstico obrigatório, sem considerar HELLP.","Trabalho de parto latente, pois dor de ombro é sinal específico de contração uterina.","Infecção urinária baixa como causa de dor hepática e hemólise."],"answer":1,"analysis":["INCORRETA. Refluxo não explica hemoglobina em queda e sinais de gravidade.","CORRETA. Dor hepática intensa com sinais de hemorragia em HELLP impõe investigar complicação hepática potencialmente fatal.","INCORRETA. Há sinais sistêmicos que exigem considerar dano hepático obstétrico.","INCORRETA. Dor escapular e instabilidade hematológica sugerem outra causa.","INCORRETA. Não há elementos urinários que expliquem o quadro."],"explanation":"Dor hepática intensa com sinais de hemorragia em HELLP impõe investigar complicação hepática potencialmente fatal.","memorizar":"HELLP + DOR HEPÁTICA INTENSA + QUEDA Hb: pensar em HEMATOMA/RUPTURA.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"dor em hipocôndrio e risco hepático","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-10","topicId":"sm-A2","stem":"Puérpera há 18 horas, previamente hipertensa na gestação, apresenta crise tônico-clônica generalizada de 80 segundos, seguida de confusão. Glicemia capilar está normal, sem história de epilepsia. Qual hipótese deve ser tratada de forma prioritária?","options":["Epilepsia primária confirmada, porque eclâmpsia não ocorre após o nascimento.","Crise psicogênica definida apenas pela confusão pós-crise.","Tratar e investigar eclâmpsia no puerpério.","Convulsão febril do adulto, pois glicemia normal afasta emergência obstétrica.","Reação fisiológica à anestesia em qualquer puérpera, sem necessidade de investigação."],"answer":2,"analysis":["INCORRETA. Eclâmpsia pode acontecer no puerpério.","INCORRETA. O contexto obstétrico exige investigar e tratar eclâmpsia.","CORRETA. Convulsão em paciente com contexto de pré-eclâmpsia pode ocorrer após o parto; ausência de gravidez atual não afasta eclâmpsia.","INCORRETA. Convulsão febril é entidade da infância e não explica quadro.","INCORRETA. Crise com confusão é emergência neurológica/obstétrica."],"explanation":"Convulsão em paciente com contexto de pré-eclâmpsia pode ocorrer após o parto; ausência de gravidez atual não afasta eclâmpsia.","memorizar":"ECLÂMPSIA pode ocorrer antes, durante ou DEPOIS do parto.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"eclâmpsia e diagnóstico","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-11","topicId":"sm-A2","stem":"Gestante de 32 semanas com pré-eclâmpsia grave relata cefaleia persistente e apresenta PA 162/110 mmHg. Após controle pressórico, discute-se prevenção de convulsões. Qual fármaco tem papel central nessa prevenção?","options":["Hidralazina como único fármaco anticonvulsivante, porque reduz a PA.","Sulfato de magnésio para profilaxia anticonvulsivante quando indicado.","Furosemida de rotina como anticonvulsivante primário.","AAS como tratamento imediato de crise eclâmptica instalada.","Insulina intravenosa porque cefaleia em gestante define hiperglicemia grave."],"answer":1,"analysis":["INCORRETA. Anti-hipertensivo não oferece a mesma proteção anticonvulsiva.","CORRETA. Magnésio reduz risco de crises eclâmpticas; anti-hipertensivos controlam PA, mas não substituem profilaxia anticonvulsivante.","INCORRETA. Diuréticos não substituem magnésio na prevenção de eclâmpsia.","INCORRETA. AAS é estratégia preventiva em populações selecionadas, não tratamento agudo.","INCORRETA. Não há evidência de crise hiperglicêmica."],"explanation":"Magnésio reduz risco de crises eclâmpticas; anti-hipertensivos controlam PA, mas não substituem profilaxia anticonvulsivante.","memorizar":"MAGNÉSIO previne/trata convulsão; ANTI-HIPERTENSIVO controla PA.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"sulfato de magnésio indicação","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sm-A2-12","topicId":"sm-A2","stem":"Puérpera com eclâmpsia está em infusão de sulfato de magnésio. Evolui com reflexos patelares abolidos, frequência respiratória de 8/min e oligúria. Qual resposta técnica deve ser priorizada?","options":["Aumentar magnésio porque reflexos abolidos demonstram subdosagem anticonvulsivante.","Manter a infusão sem reavaliação porque oligúria não modifica eliminação de magnésio.","Substituir avaliação respiratória por nova medida de proteinúria.","Suspender magnésio e oferecer suporte; avaliar gluconato de cálcio.","Aplicar AAS como antídoto específico para hipermagnesemia."],"answer":3,"analysis":["INCORRETA. Arreflexia é sinal de toxicidade, não necessidade de mais magnésio.","INCORRETA. Magnésio é eliminado por via renal.","INCORRETA. Hipoventilação é emergência imediata.","CORRETA. Arreflexia, depressão respiratória e redução da depuração renal apontam intoxicação magnésica; cálcio antagoniza efeitos quando indicado.","INCORRETA. AAS não reverte toxicidade por magnésio."],"explanation":"Arreflexia, depressão respiratória e redução da depuração renal apontam intoxicação magnésica; cálcio antagoniza efeitos quando indicado.","memorizar":"MAGNÉSIO: monitorar RESPIRAÇÃO, REFLEXOS e DIURESE; toxicidade exige interrupção.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"toxicidade do magnésio","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-13","topicId":"sm-A2","stem":"Mulher com hipertensão crônica controlada desde os 23 anos engravida. Na 29ª semana, PA piora apesar do esquema habitual, surge proteinúria nova e plaquetas caem para 91.000/mm³. Qual classificação explica a mudança?","options":["Pré-eclâmpsia sobreposta à hipertensão arterial crônica.","Hipertensão gestacional pura, porque a gravidez elimina o diagnóstico anterior.","Hipertensão de avental branco provada pela plaquetopenia.","Hipotensão fisiológica, porque houve incremento da PA.","Eclâmpsia já estabelecida mesmo sem convulsão."],"answer":0,"analysis":["CORRETA. Piora hipertensiva com proteinúria nova e lesão de órgão alvo em hipertensa preexistente sugere pré-eclâmpsia sobreposta.","INCORRETA. História de hipertensão crônica permanece relevante.","INCORRETA. A disfunção hematológica reforça condição orgânica grave.","INCORRETA. PA está pior, não reduzida.","INCORRETA. Eclâmpsia exige crise convulsiva não atribuída a outra causa."],"explanation":"Piora hipertensiva com proteinúria nova e lesão de órgão alvo em hipertensa preexistente sugere pré-eclâmpsia sobreposta.","memorizar":"HAS CRÔNICA + PROTEINÚRIA/DANO NOVO após 20 sem: pensar em PRÉ-ECLÂMPSIA SOBREPOSTA.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"hipertensão sobreposta","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-14","topicId":"sm-A2","stem":"Gestante de 36 semanas com hipertensão grave apresenta dor abdominal súbita, hipertonia uterina e sangramento vaginal escuro. Cardiotocografia sugere comprometimento fetal. Qual complicação obstétrica é prioritária?","options":["Placenta prévia típica, que costuma cursar com útero hipertônico e dor intensa.","Trabalho de parto normal sem risco fetal, apesar do sangramento e hipertonia.","Descolamento prematuro de placenta.","Rotura de bolsa isolada, porque sangue escuro é diagnóstico definitivo de líquido amniótico.","Hematoma retroplacentário excluído por haver sangramento vaginal."],"answer":2,"analysis":["INCORRETA. Placenta prévia classicamente cursa com sangramento sem dor e sem hipertonia.","INCORRETA. Os sinais são graves e não caracterizam contrações fisiológicas.","CORRETA. HAS é fator de risco para DPP; dor, hipertonia e sofrimento fetal com sangramento apontam separação placentária.","INCORRETA. Não há relato de perda hídrica nem teste confirmatório.","INCORRETA. DPP pode apresentar sangramento externo ou oculto."],"explanation":"HAS é fator de risco para DPP; dor, hipertonia e sofrimento fetal com sangramento apontam separação placentária.","memorizar":"HIPERTENSÃO + DOR + HIPERTONIA + SANGRAMENTO: suspeitar DPP.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"DPP e pré-eclâmpsia","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-15","topicId":"sm-A2","stem":"Mulher com 31 semanas e PA 178/116 mmHg persistente chega à emergência obstétrica. Sem edema pulmonar e com acesso venoso, é necessário reduzir a PA cuidadosamente. Qual princípio terapêutico é mais apropriado?","options":["Aguardar 24 horas de coleta de urina antes de tratar pressão grave.","Reduzir a PA ao mínimo possível em minutos por qualquer droga disponível.","Prescrever inibidor de ECA como opção universal de primeira linha na gestação.","Usar somente diurético em toda crise hipertensiva mesmo sem congestão.","Anti-hipertensivo de ação rápida aprovado, com redução controlada da PA."],"answer":4,"analysis":["INCORRETA. Pressão grave é emergência independentemente da proteinúria.","INCORRETA. Hipotensão brusca pode comprometer perfusão materna/fetal.","INCORRETA. IECA não é indicado na gestação por risco fetal.","INCORRETA. Diurético não é tratamento universal de HAS grave na gestação.","CORRETA. O risco de AVC materno justifica tratamento célere; a redução deve ser controlada, evitando hipoperfusão uteroplacentária."],"explanation":"O risco de AVC materno justifica tratamento célere; a redução deve ser controlada, evitando hipoperfusão uteroplacentária.","memorizar":"HAS GRAVE OBSTÉTRICA: controlar RÁPIDO, porém SEM queda excessiva.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"hipertensão grave e fármaco de ação rápida","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sm-A2-16","topicId":"sm-A2","stem":"Mulher hipertensa planeja gestação e usa losartana. Após teste positivo de gravidez, questiona se pode manter a medicação sem avaliação. Qual princípio farmacológico precisa ser observado?","options":["Losartana é preferível na gravidez porque protege a perfusão renal fetal.","A alteração só é necessária se a gestante tiver convulsão.","Evitar losartana e outros bloqueadores do SRAA na gestação.","Suspender todos os anti-hipertensivos e deixar hipertensão grave sem tratamento.","Trocar por outro ARA-II, porque o problema é exclusivo da losartana."],"answer":2,"analysis":["INCORRETA. Bloqueio do sistema renina-angiotensina traz risco fetal.","INCORRETA. A contraindicação não depende de eclâmpsia.","CORRETA. ARA-II e inibidores de ECA podem causar toxicidade fetal, especialmente renal, e são inadequados durante a gestação.","INCORRETA. É necessário ajustar a terapia com opções apropriadas e monitorização.","INCORRETA. Risco é relacionado à classe, não apenas a um fármaco."],"explanation":"ARA-II e inibidores de ECA podem causar toxicidade fetal, especialmente renal, e são inadequados durante a gestação.","memorizar":"GESTAÇÃO: evitar IECA e ARA-II; adaptar terapia com profissional.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"IECA na gestação","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"},{"id":"ouro-rigor5-sm-A2-17","topicId":"sm-A2","stem":"Gestante de 11 semanas tem histórico de pré-eclâmpsia grave em gestação anterior e hipertensão crônica. Não está hipertensa no momento. Qual intervenção preventiva deve ser discutida no pré-natal de alto risco?","options":["Considerar AAS em baixa dose para prevenção em gestante de alto risco.","Sulfato de magnésio diariamente durante toda a gestação como profilaxia domiciliar.","Anti-hipertensivo intravenoso profilático apesar de PA normal.","Aguardar 37 semanas para considerar toda prevenção, pois risco só surge no termo.","Suspender pré-natal de alto risco se a PA estiver normal em uma consulta."],"answer":0,"analysis":["CORRETA. Antecedente de pré-eclâmpsia e hipertensão crônica elevam o risco; AAS em baixa dose pode reduzir incidência quando indicado no período apropriado.","INCORRETA. Magnésio é voltado à prevenção/tratamento de convulsões em contextos específicos, não uso oral domiciliar rotineiro.","INCORRETA. Medicação IV aguda não é prevenção rotineira em gestante normotensa.","INCORRETA. A janela preventiva ocorre antes e durante o desenvolvimento placentário.","INCORRETA. Risco obstétrico é sustentado por antecedentes, não por uma aferição normal."],"explanation":"Antecedente de pré-eclâmpsia e hipertensão crônica elevam o risco; AAS em baixa dose pode reduzir incidência quando indicado no período apropriado.","memorizar":"ALTO RISCO para PE: considerar AAS profilático no período recomendado.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"AAS profilático","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sm-A2-18","topicId":"sm-A2","stem":"Em discussão de caso, o preceptor pergunta por que uma gestante com placentação anormal evolui com vasoconstrição generalizada, hipertensão e proteinúria. Qual ligação fisiopatológica é central?","options":["Aumento primário isolado da filtração glomerular que sempre reduz a PA.","Infecção urinária baixa obrigatória em toda pré-eclâmpsia.","Estímulo exclusivamente hipofisário da prolactina, sem participação da placenta.","Aumento do volume plasmático normal como único mecanismo patológico.","Disfunção placentária causa desequilíbrio angiogênico e lesão endotelial."],"answer":4,"analysis":["INCORRETA. A síndrome envolve lesão endotelial e vasoconstrição, não hiperfiltração isolada.","INCORRETA. Infecção não é requisito causal da síndrome.","INCORRETA. Disfunção placentária é elemento central na fisiopatologia.","INCORRETA. Alterações normais de volume não explicam a lesão sistêmica.","CORRETA. Invasão trofoblástica inadequada e estresse placentário favorecem desequilíbrio angiogênico e disfunção endotelial materna."],"explanation":"Invasão trofoblástica inadequada e estresse placentário favorecem desequilíbrio angiogênico e disfunção endotelial materna.","memorizar":"PRÉ-ECLÂMPSIA: PLACENTA DISFUNCIONAL → ENDOTÉLIO LESADO → VASOCONSTRIÇÃO/LESÃO ORGÂNICA.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"fisiopatologia placentária","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-19","topicId":"sm-A2","stem":"Grávida de 31 semanas com pré-eclâmpsia tem ultrassom mostrando peso fetal abaixo do percentil 3 e Doppler umbilical com resistência aumentada. Qual ligação fisiopatológica é mais coerente?","options":["O peso fetal baixo demonstra, isoladamente, infecção congênita e exclui insuficiência placentária.","Insuficiência placentária associada à restrição de crescimento fetal.","Resistência umbilical aumentada equivale a aumento seguro da nutrição fetal.","Toda restrição de crescimento prova malformação cromossômica.","Pré-eclâmpsia só afeta órgãos maternos, sem repercussão fetal."],"answer":1,"analysis":["INCORRETA. Restrição tem várias causas; Doppler e contexto hipertensivo favorecem insuficiência.","CORRETA. Placentação comprometida na pré-eclâmpsia pode elevar resistência vascular placentária e limitar oferta de oxigênio e nutrientes ao feto.","INCORRETA. Resistência maior pode refletir comprometimento vascular placentário.","INCORRETA. A causa deve ser avaliada; o quadro favorece doença placentária.","INCORRETA. Insuficiência placentária é complicação fetal importante."],"explanation":"Placentação comprometida na pré-eclâmpsia pode elevar resistência vascular placentária e limitar oferta de oxigênio e nutrientes ao feto.","memorizar":"PE pode reduzir PERFUSÃO PLACENTÁRIA → RCF e alterações Doppler.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"restrição de crescimento fetal","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-20","topicId":"sm-A2","stem":"Mulher sem hipertensão documentada na gestação procura atendimento no 6º dia após o parto por cefaleia intensa, escotomas e PA de 166/108 mmHg. Qual erro de interpretação deve ser evitado?","options":["Classificar o quadro como sempre fisiológico no puerpério, sem aferir novamente a PA.","Esperar proteinúria positiva antes de qualquer controle pressórico.","Atribuir escotomas a privação de sono sem avaliar alteração vascular.","Investigar pré-eclâmpsia pós-parto mesmo após gravidez normotensa.","Considerar que pré-eclâmpsia desaparece obrigatoriamente no momento do parto."],"answer":3,"analysis":["INCORRETA. Pressão grave com sintomas não é fisiológica.","INCORRETA. Gravidade pressórica e sintomas podem exigir conduta imediata.","INCORRETA. Sintomas visuais podem indicar acometimento neurológico.","CORRETA. Doença hipertensiva pode surgir pela primeira vez no pós-parto, e PA grave com sintomas neurológicos exige avaliação imediata.","INCORRETA. Pode persistir ou iniciar após o parto."],"explanation":"Doença hipertensiva pode surgir pela primeira vez no pós-parto, e PA grave com sintomas neurológicos exige avaliação imediata.","memorizar":"PRÉ-ECLÂMPSIA PÓS-PARTO existe mesmo após gravidez normotensa.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"puerpério e nova hipertensão","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-21","topicId":"sm-A2","stem":"Gestante de 35 semanas com síndrome HELLP, plaquetas 48.000/mm³ e coagulopatia necessita planejamento de parto. A paciente solicita analgesia neuroaxial imediata. Qual elemento torna essa escolha potencialmente perigosa?","options":["Plaquetopenia/coagulopatia elevam risco de hematoma após neuroeixo.","HELLP garante coagulação normal porque o principal órgão afetado é a placenta.","O risco anestésico depende apenas da PA e ignora plaquetas.","Baixas plaquetas são equivalentes a anestesia sem risco por reduzir sangramento.","O anestésico pode ser escolhido exclusivamente por preferência da gestante sem avaliação de risco."],"answer":0,"analysis":["CORRETA. Alterações hemostáticas na HELLP modificam o risco de procedimentos neuroaxiais e impõem avaliação especializada.","INCORRETA. A síndrome envolve alterações hematológicas importantes.","INCORRETA. Hemostasia é fundamental para analgesia neuroaxial.","INCORRETA. Plaquetopenia eleva preocupação hemorrágica.","INCORRETA. Escolha informada exige considerar contraindicações e risco neurológico."],"explanation":"Alterações hemostáticas na HELLP modificam o risco de procedimentos neuroaxiais e impõem avaliação especializada.","memorizar":"HELLP + PLAQUETAS MUITO BAIXAS: cautela com analgesia NEUROAXIAL.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"plaquetopenia e anestesia","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-22","topicId":"sm-A2","stem":"Gestante de 37 semanas chega com náuseas intensas, icterícia, hipoglicemia, alteração do INR e disfunção renal. Plaquetas estão discretamente reduzidas. Qual diferencial deve ser ponderado além de HELLP?","options":["Colestase simples da gravidez como explicação obrigatória para hipoglicemia e coagulopatia.","Hiperêmese gravídica habitual do primeiro trimestre, apesar das 37 semanas e coagulopatia.","Hipertensão gestacional isolada, pois icterícia é critério diagnóstico de HAS.","Hepatite viral descartada automaticamente sem qualquer exame por ser gestante.","Esteatose hepática aguda da gestação é diferencial relevante."],"answer":4,"analysis":["INCORRETA. Colestase costuma destacar prurido e ácidos biliares, não falência hepática fulminante típica.","INCORRETA. A cronologia e disfunção sistêmica apontam outra condição.","INCORRETA. Icterícia e hipoglicemia indicam investigar doença hepática.","INCORRETA. Etiologias hepáticas devem ser diferenciadas, não descartadas por gravidez.","CORRETA. Hipoglicemia e falência sintética hepática são pistas relevantes de esteatose hepática aguda; HELLP pode compartilhar alterações, mas o diferencial muda abordagem."],"explanation":"Hipoglicemia e falência sintética hepática são pistas relevantes de esteatose hepática aguda; HELLP pode compartilhar alterações, mas o diferencial muda abordagem.","memorizar":"TERCEIRO TRIMESTRE + HIPOGLICEMIA + COAGULOPATIA: considerar ESTEATOSE HEPÁTICA AGUDA.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"fígado gorduroso agudo versus HELLP","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-23","topicId":"sm-A2","stem":"Grávida de 30 semanas com hipertensão de início recente evolui com dispneia, ortopneia, estertores difusos e hipoxemia. Radiografia à beira do leito sugere congestão pulmonar. Qual interpretação muda a gravidade do caso?","options":["Tratar como rinite fisiológica e liberar porque ortopneia é comum na gravidez.","Requerer proteinúria nefrótica antes de reconhecer gravidade respiratória.","Edema pulmonar caracteriza manifestação grave da pré-eclâmpsia.","Infundir repetidos bolus de cristalóide sem reavaliar congestão.","Considerar que edema pulmonar exclui pré-eclâmpsia e prova cardiopatia primária."],"answer":2,"analysis":["INCORRETA. Hipoxemia e estertores difusos são sinais de insuficiência respiratória.","INCORRETA. Edema pulmonar é critério de gravidade por si.","CORRETA. Disfunção endotelial, alterações hemodinâmicas e sobrecarga podem causar congestão pulmonar; é grave independentemente de proteinúria.","INCORRETA. Sobrecarga hídrica pode agravar edema pulmonar.","INCORRETA. A condição pode complicar pré-eclâmpsia, embora exija diferenciais."],"explanation":"Disfunção endotelial, alterações hemodinâmicas e sobrecarga podem causar congestão pulmonar; é grave independentemente de proteinúria.","memorizar":"PRÉ-ECLÂMPSIA + EDEMA PULMONAR = GRAVIDADE.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"edema pulmonar","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-24","topicId":"sm-A2","stem":"Gestante de 38 semanas tem hipertensão gestacional persistente, sem sinais de gravidade, com crescimento fetal e avaliação de bem-estar adequados. Qual princípio obstétrico orienta a decisão sobre interrupção?","options":["Aguardar obrigatoriamente 42 semanas para qualquer gestante hipertensa sem proteinúria.","Avaliar parto programado no termo conforme quadro materno-fetal.","Indicar cesárea automática em todas as gestantes com PA acima de 140/90.","Suspender pré-natal, porque a PA não apresenta picos graves.","Usar magnésio por semanas em casa como substituto para planejar o nascimento."],"answer":1,"analysis":["INCORRETA. A doença hipertensiva favorece planejamento em idade mais precoce conforme protocolo.","CORRETA. A idade gestacional no termo modifica o equilíbrio entre risco de progressão da hipertensão e benefício fetal da manutenção.","INCORRETA. A via de parto depende das condições obstétricas, não apenas da classificação da hipertensão.","INCORRETA. A vigilância persiste até o parto e puerpério.","INCORRETA. O manejo e tempo do parto dependem de gravidade e idade gestacional."],"explanation":"A idade gestacional no termo modifica o equilíbrio entre risco de progressão da hipertensão e benefício fetal da manutenção.","memorizar":"HIPERTENSÃO A TERMO: considerar PARTO planejado; VIA depende de obstetrícia.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"planejamento parto a termo","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sm-A2-25","topicId":"sm-A2","stem":"Gestante de 27 semanas com pré-eclâmpsia e pressão controlada após estabilização, sem sinais atuais de gravidade, está em centro terciário com vigilância materno-fetal rigorosa. Qual princípio de manejo pode ser discutido?","options":["Indução imediata obrigatória em toda pré-eclâmpsia de 27 semanas, mesmo sem deterioração e sem avaliar contexto.","Alta sem seguimento porque a pressão respondeu a uma dose.","Manter gravidez independentemente de piora neurológica ou descolamento.","Conduta expectante selecionada com vigilância e critérios de interrupção.","Administrar sedação profunda de rotina para evitar crises enquanto se aguarda termo."],"answer":3,"analysis":["INCORRETA. A decisão deve equilibrar gravidade, IG, disponibilidade e critérios de segurança.","INCORRETA. A doença pode progredir e exige vigilância.","INCORRETA. Sinais graves mudam a indicação e podem exigir interrupção.","CORRETA. Em pré-eclâmpsia antes do termo, riscos maternos e benefícios fetais podem justificar observação especializada em pacientes estáveis e elegíveis; não é decisão automática.","INCORRETA. Medida não é estratégia preventiva de rotina."],"explanation":"Em pré-eclâmpsia antes do termo, riscos maternos e benefícios fetais podem justificar observação especializada em pacientes estáveis e elegíveis; não é decisão automática.","memorizar":"PE PRÉ-TERMO ESTÁVEL: expectância só quando SELECIONADA E VIGIADA.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"prematuridade e manejo expectante","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-26","topicId":"sm-A2","stem":"Gestante de 29 semanas com PA de 152/96 mmHg descreve cefaleia nova persistente, intensa, que não melhora com tratamento habitual, além de escotomas. Exames laboratoriais ainda estão em processamento. Qual mudança na gravidade decorre da clínica?","options":["Sem PA ≥160/110, pré-eclâmpsia grave está categoricamente excluída.","Sintomas neurológicos persistentes exigem avaliação de gravidade.","Aguardar convulsão para classificar risco neurológico.","Atribuir a alteração visual à dilatação fisiológica das pupilas na gravidez.","Diagnosticar diabetes gestacional como única causa das fotopsias."],"answer":1,"analysis":["INCORRETA. Disfunção orgânica/sintomas graves também definem a preocupação clínica.","CORRETA. Cefaleia refratária e alteração visual no contexto de hipertensão gestacional são sinais de alarme e não precisam acompanhar pico pressórico grave.","INCORRETA. Profilaxia e manejo devem anteceder eclâmpsia.","INCORRETA. Escotomas e cefaleia exigem avaliação neurológica e obstétrica.","INCORRETA. Não há dados glicêmicos que expliquem o quadro."],"explanation":"Cefaleia refratária e alteração visual no contexto de hipertensão gestacional são sinais de alarme e não precisam acompanhar pico pressórico grave.","memorizar":"CEFALÉIA PERSISTENTE + ESCOTOMAS em HAS gestacional: GRAVIDADE mesmo sem PA extrema.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"sinais neurológicos de gravidade","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-27","topicId":"sm-A2","stem":"Mulher de 33 semanas com hipertensão nova tem plaquetas que caíram de 205.000 para 88.000/mm³ em poucos dias, bilirrubina indireta elevada e LDH alto. Qual avaliação é essencial para interpretar o padrão?","options":["Classificar como plaquetopenia gestacional típica independentemente da contagem.","Considerar LDH elevado marcador isolado de diabetes gestacional.","Pesquisar HELLP e hemólise microangiopática com exames complementares.","Dispensar avaliação renal porque hemólise não afeta rim.","Decidir tipo de parto apenas pela bilirrubina sem reexaminar quadro sistêmico."],"answer":2,"analysis":["INCORRETA. A forma gestacional costuma ser leve; queda acentuada e hemólise exigem investigação.","INCORRETA. LDH pode refletir lesão/hemólise e precisa de contexto.","CORRETA. Plaquetopenia rápida e intensa com sinais de hemólise sugere processo microangiopático, não simples alteração fisiológica.","INCORRETA. Microangiopatias podem comprometer diversos órgãos.","INCORRETA. A decisão depende de gravidade global e avaliação obstétrica."],"explanation":"Plaquetopenia rápida e intensa com sinais de hemólise sugere processo microangiopático, não simples alteração fisiológica.","memorizar":"PLAQUETAS <100 mil + SUSPEITA de HEMÓLISE: avaliar HELLP e microangiopatias.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"preeclâmpsia e trombocitopenia diferencial","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-28","topicId":"sm-A2","stem":"Grávida de 25 semanas com lúpus conhecido evolui com hipertensão e proteinúria. Há queda de complemento, anti-DNA elevado e sedimento urinário com cilindros hemáticos. Qual diagnóstico diferencial deve ser fortemente considerado?","options":["Pré-eclâmpsia é o único diagnóstico possível após 20 semanas, independentemente de autoanticorpos.","Hipertensão gestacional não complicada, pois proteinúria e cilindros não têm relevância.","Infecção urinária baixa isolada como explicação obrigatória para complemento baixo.","Considerar nefrite lúpica ativa coexistente com pré-eclâmpsia.","Trombose venosa profunda como causa direta de proteinúria com cilindros hemáticos."],"answer":3,"analysis":["INCORRETA. Doença renal inflamatória pode surgir ou exacerbar na gestação.","INCORRETA. Sedimento ativo sugere dano glomerular.","INCORRETA. Marcadores imunológicos e cilindros hemáticos apontam outra possibilidade.","CORRETA. Complemento baixo, anti-DNA elevado e sedimento ativo orientam doença glomerular inflamatória, que pode mimetizar ou coexistir com PE.","INCORRETA. TVP não explica padrão de nefrite ativa."],"explanation":"Complemento baixo, anti-DNA elevado e sedimento ativo orientam doença glomerular inflamatória, que pode mimetizar ou coexistir com PE.","memorizar":"LES + C3/C4 baixos + anti-DNA alto + SEDIMENTO ATIVO: diferenciar NEFRITE de PE.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"nefrite lúpica versus pré-eclâmpsia","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-29","topicId":"sm-A2","stem":"Gestante de 32 semanas com epilepsia controlada há cinco anos apresenta primeira crise na gestação, com PA 174/114 mmHg e cefaleia persistente nas horas anteriores. Qual atitude diagnóstica é mais segura?","options":["Classificar toda convulsão como epilepsia porque ela já possui esse diagnóstico.","Esperar recorrência da crise para reconhecer gravidade, pois episódio isolado não importa.","A PA elevada é proteção contra eclâmpsia quando a paciente usa anticonvulsivante.","A convulsão prova hiperêmese sem relação com doença hipertensiva.","Tratar eclâmpsia possível mesmo em paciente epiléptica."],"answer":4,"analysis":["INCORRETA. O contexto obstétrico cria outra causa potencial e urgente.","INCORRETA. Uma crise com HAS grave requer atenção imediata.","INCORRETA. A hipertensão é fator de gravidade, não de proteção.","INCORRETA. Os dados não sustentam esse diagnóstico.","CORRETA. Antecedente de epilepsia não exclui eclâmpsia quando surgem HAS grave e sintomas sugestivos de acometimento cerebral."],"explanation":"Antecedente de epilepsia não exclui eclâmpsia quando surgem HAS grave e sintomas sugestivos de acometimento cerebral.","memorizar":"EPILEPSIA PRÉVIA NÃO DESCARTA ECLÂMPSIA se surgem HAS grave e sinais neurológicos.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"distinguir eclâmpsia de epilepsia","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sm-A2-30","topicId":"sm-A2","stem":"Gestante de 37 semanas com pré-eclâmpsia sem sinais atuais de gravidade tem apresentação cefálica, colo favorável e vitalidade fetal tranquilizadora. A paciente acredita que toda pré-eclâmpsia obriga cesárea. Qual orientação é mais adequada?","options":["A via de parto depende das condições obstétricas e materno-fetais.","Realizar cesárea automaticamente em qualquer PA ≥140/90, independentemente de condições obstétricas.","Proibir indução em toda mulher com pré-eclâmpsia.","Adiar qualquer parto até surgir crise convulsiva para então decidir via.","Ignorar o estado fetal porque só a pressão determina a via."],"answer":0,"analysis":["CORRETA. O diagnóstico de PE define risco e momento do nascimento, mas não indica cesárea por si só.","INCORRETA. Hipertensão leve por si só não determina via cirúrgica.","INCORRETA. Indução pode ser considerada quando apropriada.","INCORRETA. O planejamento deve anteceder deterioração.","INCORRETA. Bem-estar fetal e condições obstétricas são fundamentais."],"explanation":"O diagnóstico de PE define risco e momento do nascimento, mas não indica cesárea por si só.","memorizar":"PE NÃO = cesárea obrigatória; definir MOMENTO e VIA por avaliação materno-fetal.","source":"Biblioteca da Trilha de Ouro SDMII A2; revisão autoral sobre distúrbios hipertensivos da gestação; confirmar condutas no protocolo obstétrico vigente e materiais da professora.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Síndromes hipertensivas gestacionais","group":"P2 • Saúde da Mulher II","competence":"cesárea não obrigatória","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"}]};
